  { name: "Laptop", price: 3000 },
  { name: "T-shirt", price: 49 },
  { name: "Phone", price: 1500 },
];

const names = products.map(p => p.name);
console.log(names); // ['Laptop', 'T-shirt', 'Phone']

const products = [
  { name: "Laptop", price: 3000 },
  { name: "T-shirt", price: 49 },
];

const discounted = products.map(p => ({
  ...p,
  price: p.price * 0.9,
  discounted: true,
}));

console.log(discounted);
// [{ name: 'Laptop', price: 2700, discounted: true },
//  { name: 'T-shirt', price: 44.1, discounted: true }]

