const temperatury = [15, 22, 8, 30, 19];
const fahrenheit = temperatury.map(c => c * 9 / 5 + 32);
console.log(fahrenheit); // [59, 71.6, 46.4, 86, 66.2]

const pracownicy = [{ imie: "Marta" }, { imie: "Tomek" }, { imie: "Ola" }];
const imiona = pracownicy.map(p => p.imie);
console.log(imiona); // ['Marta', 'Tomek', 'Ola']

const pracownicy = [
  { imie: "Marta", dzial: "IT" },
  { imie: "Tomek", dzial: "Sprzedaz" }
];

const opisy = pracownicy.map(p => `${p.imie} - ${p.dzial}`);
console.log(opisy); // ['Marta - IT', 'Tomek - Sprzedaz']

const zwierzeta = ["kot", "pies", "papuga"];
const dlugosci = zwierzeta.map(z => z.length);
console.log(dlugosci); // [3, 4, 6]

const temperatury = [15, 22, 8, 30];
const opisane = temperatury.map(c => ({ stopnie: c, czyCieplo: c >= 20 }));
console.log(opisane);
// [{ stopnie: 15, czyCieplo: false }, { stopnie: 22, czyCieplo: true },
//  { stopnie: 8, czyCieplo: false }, { stopnie: 30, czyCieplo: true }]

const produkty = [{ nazwa: "Laptop", cena: 1000 }, { nazwa: "Mysz", cena: 50 }];

const przecenione = produkty.map(p => ({
  ...p,
  cena: p.cena * 0.9,
  przecena: true
}));

console.log(przecenione);
// [{ nazwa: 'Laptop', cena: 900, przecena: true }, { nazwa: 'Mysz', cena: 45, przecena: true }]
console.log(produkty);
// [{ nazwa: 'Laptop', cena: 1000 }, { nazwa: 'Mysz', cena: 50 }] - NIEZMIENIONE

const imiona = ["ala", "bartek", "celina"];
const poprawione = imiona.map(i => i.charAt(0).toUpperCase() + i.slice(1));
console.log(poprawione); // ['Ala', 'Bartek', 'Celina']

const produkty = ["Laptop", "Mysz"];

produkty.map(p => {
  console.log(`Produkt: ${p}`);
});
// BLEDNIE: map() tworzy NOWA tablice [undefined, undefined] (bo funkcja
// nie ma return), ktora jest CALKOWICIE ignorowana - forEach() bylby
// lepszym wyborem, bo NIE tworzy zadnej zbednej tablicy wynikowej
